import{_ as s,o as t,c as o,a2 as r}from"./chunks/framework.uw_ZoRon.js";const g=JSON.parse('{"title":"Why RUSM?","description":"","frontmatter":{},"headers":[],"relativePath":"introduction/why-rusm.md","filePath":"introduction/why-rusm.md"}'),a={name:"introduction/why-rusm.md"};function n(i,e,c,l,h,u){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="why-rusm" tabindex="-1">Why RUSM? <a class="header-anchor" href="#why-rusm" aria-label="Permalink to &quot;Why RUSM?&quot;">​</a></h1><p>RUSM gives you the BEAM&#39;s process model — cheap isolated processes, &quot;let it crash&quot; supervision, built-in distribution, live introspection — but for <strong>any language</strong>, compiled to <strong>WebAssembly</strong>, on a Rust + Tokio runtime that is lightweight and <em>crazy fast</em>. Elixir&#39;s concurrency and fault tolerance, in Rust, running Wasm.</p><h2 id="the-itch" tabindex="-1">The itch <a class="header-anchor" href="#the-itch" aria-label="Permalink to &quot;The itch&quot;">​</a></h2><p>My Elixir years left me wanting one thing: the BEAM&#39;s process model, but able to run <strong>any</strong> language on infrastructure that is lightweight, optimal, and fast. <a href="https://github.com/lunatic-solutions/lunatic" target="_blank" rel="noreferrer">Lunatic</a> proved the idea — a Wasm instance as a process, with supervisors and a distributed registry — and pitched it perfectly. <strong>RUSM takes that idea further</strong>: the modern <strong>component model</strong> (not just core modules), guests in <strong>Rust, TypeScript, and Go</strong> (not Rust alone), first-class <strong>HTTP/WS/SSE serving</strong>, and a <strong>QUIC + mutual-TLS cluster</strong> — all on a current Wasmtime, and every claim on this page is measured on a live dashboard, not asserted.</p><h2 id="what-a-process-should-be" tabindex="-1">What a process should be <a class="header-anchor" href="#what-a-process-should-be" aria-label="Permalink to &quot;What a process should be&quot;">​</a></h2><p>RUSM is built around a single idea: <strong>a process is an isolated WebAssembly instance</strong> — its own stack, heap, syscalls, and permissions. Almost everything else falls out of that one decision:</p><ul><li><strong>Crash isolation</strong> — one process can never corrupt another; a guest trap crashes only <em>that</em> process, never its neighbours or the node.</li><li><strong>Massive, cheap concurrency</strong> — processes are Tokio tasks multiplexed M:N over a few OS threads, targeting hundreds of thousands of spawns per second (~2.4M/sec measured).</li><li><strong>Write blocking code, get async</strong> — Wasmtime fibers suspend a guest&#39;s &quot;blocking&quot; call while the host awaits; guests never see <code>async</code>.</li><li><strong>Survivable failure</strong> — links, monitors, and supervisors, Erlang-style.</li><li><strong>First-class clusters</strong> — nodes connect over QUIC + mutual TLS; processes spawn and message across nodes, and you can <strong>attach a live REPL/observer to a running node</strong> (like <code>iex --remsh</code>).</li></ul><h2 id="proof-not-promises" tabindex="-1">Proof, not promises <a class="header-anchor" href="#proof-not-promises" aria-label="Permalink to &quot;Proof, not promises&quot;">​</a></h2><p>RUSM ships with a <strong>benchmark + live-observer dashboard</strong> that stress-tests the runtime and streams real latency, throughput, peak concurrency, and a live process table — with an observer-on / observer-off toggle to show that observability is nearly free. Network-facing rates (HTTP/WS/SSE throughput, connection establishment) are <strong>earned out-of-process</strong> by the <code>rusm-loadtest</code> driver against a live <code>rusm serve</code> port — e.g. ~34k sandboxed-process-per-connection WS establishments/sec — measured, never asserted.</p><p>It was built in small, test-driven <a href="/rusm/about/roadmap">phases</a>, each one teaching a single concept: the Wasm-free OTP core first (processes, messaging, supervision, management, TCP), then Wasmtime as the process backend, then real component hosting, clustering over QUIC+TLS, and serving. Every dashboard scenario now runs on real data.</p><p>Next: see <a href="/rusm/introduction/what-you-get">what you get</a> for the full feature map, or go straight to the <a href="/rusm/introduction/quick-start">quick start</a>.</p>',11)])])}const p=s(a,[["render",n]]);export{g as __pageData,p as default};
